input: {
    "context": "1元=10角；4元5角=4.5元，3元8角=3.8元。共花4.5+3.8=8.3元，找回10-8.3=1.7元。",
    "statements": [
        "4元5角 equals 4.5元.",
        "3元8角 equals 3.8元.",
        "The total spent is 4.5 + 3.8 = 8.3元.",
        "The change returned is 10.0 - 8.3 = 1.7元.",
        "The total spent is 8.3元 and the change is 1.7元."
    ]
}
